#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <appmodel.h>
#include <userenv.h>
#include <sddl.h>
#include <stdio.h>
#include <string>
#include <vector>
#include <cstring>
#pragma comment(lib,"advapi32.lib")
#pragma comment(lib,"userenv.lib")
static const wchar_t* PIPE_NAME=L"\\\\.\\pipe\\TokenSaver.Phone02.MsixPoA";
static std::wstring SidString(PSID sid){if(!sid||!IsValidSid(sid))return L"UNAVAILABLE";LPWSTR p=nullptr;if(!ConvertSidToStringSidW(sid,&p))return L"UNAVAILABLE";std::wstring s=p;LocalFree(p);return s;}
static std::wstring TokenSid(HANDLE t,TOKEN_INFORMATION_CLASS c){DWORD n=0;GetTokenInformation(t,c,nullptr,0,&n);if(!n)return L"UNAVAILABLE";std::vector<BYTE>b(n);if(!GetTokenInformation(t,c,b.data(),n,&n))return L"UNAVAILABLE";PSID sid=c==TokenUser?reinterpret_cast<TOKEN_USER*>(b.data())->User.Sid:reinterpret_cast<TOKEN_APPCONTAINER_INFORMATION*>(b.data())->TokenAppContainer;return SidString(sid);}
static std::wstring PackageValue(HANDLE t,bool full){HMODULE mod=GetModuleHandleW(L"kernel32.dll");const char* name=full?"GetPackageFullNameFromToken":"GetPackageFamilyNameFromToken";using QueryFn=LONG(WINAPI*)(HANDLE,UINT32*,PWSTR);auto fn=reinterpret_cast<QueryFn>(GetProcAddress(mod,name));if(!fn)return L"API_UNAVAILABLE";UINT32 n=0;LONG rc=fn(t,&n,nullptr);if(rc!=ERROR_INSUFFICIENT_BUFFER||!n)return L"NO_PACKAGE_IDENTITY";std::vector<wchar_t>b(n);rc=fn(t,&n,b.data());return rc==ERROR_SUCCESS?std::wstring(b.data()):L"QUERY_FAILED";}
static int Client(){HANDLE h=CreateFileW(PIPE_NAME,GENERIC_READ|GENERIC_WRITE,0,nullptr,OPEN_EXISTING,0,nullptr);if(h==INVALID_HANDLE_VALUE){wprintf(L"CLIENT_PIPE_FAIL=%lu\n",GetLastError());return 2;}const char*m="MSIX_TEST_CLIENT_HELLO";DWORD n=0;BOOL ok=WriteFile(h,m,(DWORD)strlen(m),&n,nullptr);wprintf(L"CLIENT_SENT=%lu\n",n);CloseHandle(h);return ok?0:3;}
static int Supervisor(const wchar_t* packageFamily){HANDLE self=nullptr;if(!OpenProcessToken(GetCurrentProcess(),TOKEN_QUERY,&self))return 4;std::wstring userSid=TokenSid(self,TokenUser);CloseHandle(self);PSID appSid=nullptr;LONG derive=DeriveAppContainerSidFromAppContainerName(packageFamily,&appSid);if(derive!=ERROR_SUCCESS||!appSid){wprintf(L"PACKAGE_APPCONTAINER_SID_DERIVE_FAILED rc=%ld\n",derive);return 5;}std::wstring appSidText=SidString(appSid);std::wstring sddl=L"D:P(A;;GA;;;"+userSid+L")(A;;GA;;;"+appSidText+L")S:(ML;;NW;;;LW)";PSECURITY_DESCRIPTOR sd=nullptr;if(!ConvertStringSecurityDescriptorToSecurityDescriptorW(sddl.c_str(),SDDL_REVISION_1,&sd,nullptr)){wprintf(L"SDDL_FAIL=%lu\n",GetLastError());FreeSid(appSid);return 6;}SECURITY_ATTRIBUTES sa{sizeof(sa),sd,FALSE};HANDLE p=CreateNamedPipeW(PIPE_NAME,PIPE_ACCESS_DUPLEX,PIPE_TYPE_MESSAGE|PIPE_READMODE_MESSAGE|PIPE_WAIT|PIPE_REJECT_REMOTE_CLIENTS,1,4096,4096,10000,&sa);LocalFree(sd);if(p==INVALID_HANDLE_VALUE){wprintf(L"PIPE_FAIL=%lu\n",GetLastError());FreeSid(appSid);return 7;}wprintf(L"SUPERVISOR_READY USER_SID=%s EXPECTED_APPCONTAINER_SID=%s\n",userSid.c_str(),appSidText.c_str());BOOL c=ConnectNamedPipe(p,nullptr)?TRUE:(GetLastError()==ERROR_PIPE_CONNECTED);if(!c){wprintf(L"PIPE_CONNECT_FAIL=%lu\n",GetLastError());CloseHandle(p);FreeSid(appSid);return 8;}char msg[256]{};DWORD got=0;BOOL rd=ReadFile(p,msg,sizeof(msg)-1,&got,nullptr);BOOL imp=rd&&ImpersonateNamedPipeClient(p);HANDLE t=nullptr;BOOL opened=imp&&OpenThreadToken(GetCurrentThread(),TOKEN_QUERY,TRUE,&t);DWORD app=0,n=0;if(opened)GetTokenInformation(t,TokenIsAppContainer,&app,sizeof(app),&n);std::wstring user=opened?TokenSid(t,TokenUser):L"UNAVAILABLE";std::wstring ac=opened?TokenSid(t,TokenAppContainerSid):L"UNAVAILABLE";std::wstring full=opened?PackageValue(t,true):L"UNAVAILABLE";std::wstring family=opened?PackageValue(t,false):L"UNAVAILABLE";if(opened)CloseHandle(t);if(imp)RevertToSelf();wprintf(L"SUPERVISOR_CLIENT_BYTES=%lu READ=%u IMPERSONATE=%u TOKEN_OPEN=%u\n",got,rd,imp,opened);wprintf(L"TOKEN_USER_SID=%s\nTOKEN_IS_APPCONTAINER=%u\nTOKEN_APPCONTAINER_SID=%s\nTOKEN_PACKAGE_FULL_NAME=%s\nTOKEN_PACKAGE_FAMILY_NAME=%s\n",user.c_str(),app?1:0,ac.c_str(),full.c_str(),family.c_str());wprintf(L"EXPECTED_APPCONTAINER_MATCH=%u\nCLIENT_MESSAGE=%S\n",ac==appSidText?1:0,msg);FlushFileBuffers(p);DisconnectNamedPipe(p);CloseHandle(p);FreeSid(appSid);return opened?0:9;}
int wmain(int argc,wchar_t**argv){if(argc>1&&wcscmp(argv[1],L"--supervisor")==0){if(argc<3)return 10;return Supervisor(argv[2]);}return Client();}
